	include 'all.macros'	include 'e16.locator'MMLoader	PROCTrue	equ $FFFFFalse	equ 0MyHandle	equ 0MyPointer	equ 4Ptr	equ 8TheUserID	equ $B005	phk	plb	lda >$C061	and #$0080	beq @1	brk $15@1;-----------------------------------------------------------;; Unload last patch;	pha	; space for result	PushWord #TheUserID	PushWord #0	_UserShutdown	pla;-----------------------------------------------------------;; Load this one.;	pha	; space for dir page stack size	pha	; space for addr of	dir page stack seg	pha	; space for starting addr	pha	pha	; space for user id	PushWord #TheUserID	; user id	PushLong #TheName	; ptr to path name	PushWord #True	_InitialLoad	bcs Die	pla	; ignore userid	pla	; put starting address	sta TableAddress	pla	sta TableAddress+2	pla	; ignore dir page	pla	; ignore dir page size	lda >$C062	and #$0080	beq @NoBreak	brk 17@NoBreak	PushWord #1	; system call	PushWord #5	; install the patch	PushLong TableAddress	_SetTSPtr	_SetDefaultTPT	_Quit QuitParams	rtlQuitParams	DC.L 0	DC.W 0TheName	str '1/DESK.IN.RAM'  ;'*/SYSTEM/SYSTEM.SETUP/DESK.IN.RAM'TableAddress	DS.B 4Die		; 	pha	PushLong #ErrorString	_SysFailMgrErrorString	str 'Could not load.  Error was $'	ENDP	END